        errThread.join(1000);
        int result = process.exitValue();
        LOG.debug("exit value for {}: {}", checkCmd[0], result);
        for (int err : errorValue) {
            if (result == err) {
                return false;
            }
        }
        return true;
    } catch (IOException | InterruptedException | TimeoutException e) {
        LOG.debug("exception trying to run " + checkCmd[0], e);
        return false;
    } catch (SecurityException se) {
        throw se;
    } catch (Error err) {
        if (err.getMessage() != null && (err.getMessage().contains("posix_spawn") || err.getMessage().contains("UNIXProcess"))) {
